.order-section {
  border-radius: 10px;
  margin: 10px;
  background-color: #FFFFFF;

  .top {
    position: relative;
    height: 42px;

    &::after {
      content: '';
      position: absolute;
      right: 16px;
      bottom: 0;
      left: 16px;
      height: 1px;
      background-color: #EEEEEE;
    }

    .item {
      flex: 1;
      padding-left: 16px;
      font-size: 13px;
      color: #999999;
    }

    .value {
      margin-left: 4px;
      font-size: 14px;
      color: #333333;
    }
  }

  .section-header {
    padding: 16px 12px 0;
    font-weight: 500;
    font-size: 15px;
    line-height: 21px;
    color: #333333;
  }

  .arrow {
    font-weight: 400;
    font-size: 13px;
    line-height: 18px;
    color: #999999;
  }

  .mobiconfont {
    font-size: 12px;
  }

  .section-content {
    padding: 14px 0 18px;

    .item {
      flex: 1;
      text-align: center;
      font-size: 13px;
      line-height: 18px;
      color: #333333;
    }

    .icon {
      margin-bottom: 9px;
    }

    .mobiconfont {
      font-size: 24px;
    }
  }
}
